import * as T from './vendor/three.js';
export function createWaterWorld(scene,world){
 const {hydro,coast}=world,cache=new Map();let serial=0,lastSplash=null,underwater=false,savedFog=null;
 function oceanNode(ix,iz){const x=ix*6,z=iz*6,key=ix+','+iz;if(cache.has(key))return cache.get(key);if(coast.isLand(x,z))return Math.min(world.rawGround(x,z),coast.seaLevel-.1);let distance=220;for(const r of [3,7,15,30,60,120,220]){let found=false;for(let i=0;i<8;i++){const a=i*Math.PI/4;if(coast.isLand(x+Math.cos(a)*r,z+Math.sin(a)*r)){distance=r*.65;found=true;break}}if(found)break}const raw=world.rawGround(x,z),bed=Math.min(raw,coast.seaLevel-(.25+distance*.095));if(cache.size>12000)cache.clear();cache.set(key,bed);return bed}
 function oceanBed(x,z){const ix=Math.floor(x/6),iz=Math.floor(z/6),u=x/6-ix,v=z/6-iz;return T.MathUtils.lerp(T.MathUtils.lerp(oceanNode(ix,iz),oceanNode(ix+1,iz),u),T.MathUtils.lerp(oceanNode(ix,iz+1),oceanNode(ix+1,iz+1),u),v)}
 function at(x,z){const river=hydro.waterAt(x,z);if(river&&(!coast||river.y>=coast.seaLevel-.08))return river;if(coast&&!coast.isLand(x,z)){const bed=oceanBed(x,z);return{kind:'sea',y:coast.seaLevel,bed,depth:coast.seaLevel-bed,flow:{x:0,z:0,speed:0}}}return river}
 const supported=(x,z,y)=>{if(world.network.onBridge?.(x,z,y)){const hit=world.network.at?.(x,z,true);if(hit&&Math.abs(world.network.height(hit.r,hit.i,hit.t,x,z)-(y-2))<.70)return true}const rail=world.railways?.at?.(x,z,0);return !!rail&&rail.s.track.bridge&&rail.d<1.8&&Math.abs(rail.y-(y-2))<.70};
 const rings=Array.from({length:12},()=>{const g=new T.RingGeometry(.88,1,40);g.rotateX(-Math.PI/2);const m=new T.Mesh(g,new T.MeshBasicMaterial({color:'#dbe9dc',transparent:true,opacity:0,depthWrite:false,side:T.DoubleSide}));m.visible=false;scene.add(m);return{mesh:m,age:100,life:2,power:1}}),particles=[],positions=new Float32Array(256*3),particleGeometry=new T.BufferGeometry();particleGeometry.setAttribute('position',new T.BufferAttribute(positions,3).setUsage(T.DynamicDrawUsage));const spray=new T.Points(particleGeometry,new T.PointsMaterial({color:'#d9eee4',size:.075,transparent:true,opacity:.7,depthWrite:false}));spray.frustumCulled=false;particleGeometry.setDrawRange(0,0);scene.add(spray);
 const bedGeometry=new T.PlaneGeometry(400,400,50,50);bedGeometry.rotateX(-Math.PI/2);const seaBed=new T.Mesh(bedGeometry,new T.MeshStandardMaterial({color:'#7b8775',map:hydro.bedTexture||null,roughness:1}));seaBed.visible=false;seaBed.frustumCulled=false;scene.add(seaBed);let bedCell='';
 const veil=typeof document!=='undefined'?document.createElement('div'):null;if(veil){veil.id='water-veil';veil.style.cssText='position:fixed;inset:0;pointer-events:none;z-index:3;opacity:0;background:radial-gradient(ellipse,rgba(12,74,77,.06),rgba(6,48,57,.52));transition:opacity .18s';document.body.append(veil)}
 function splash(x,y,z,power=3){serial++;lastSplash={serial,power};for(let k=0;k<3;k++){const r=rings.reduce((a,b)=>a.age/a.life>b.age/b.life?a:b);r.age=-k*.11;r.life=1.6+power*.025;r.power=Math.min(5,.65+power*.10);r.mesh.position.set(x,y+.018+k*.004,z)}for(let i=0;i<Math.min(48,8+power*2);i++){if(particles.length>=256)particles.shift();const a=Math.random()*Math.PI*2,v=.5+Math.random()*Math.min(3,power*.18);particles.push({x,y:y+.02,z,vx:Math.cos(a)*v,vy:1+Math.random()*Math.min(5,power*.30),vz:Math.sin(a)*v,life:.6+Math.random()*.6})}}
 function update(dt,camera,lighting){const wasUnderwater=underwater,water=at(camera.position.x,camera.position.z);underwater=!!water&&camera.position.y<water.y-.08;if(veil)veil.style.opacity=underwater?'1':'0';if(underwater&&scene.fog.far>31)savedFog={near:scene.fog.near,far:scene.fog.far,color:scene.fog.color.clone()};if(!underwater&&wasUnderwater&&savedFog&&scene.fog.far<=31){scene.fog.near=savedFog.near;scene.fog.far=savedFog.far;scene.fog.color.copy(savedFog.color)}if(underwater){scene.fog.color.set(water.kind==='sea'?'#225d65':'#335e53');scene.fog.near=.20;scene.fog.far=water.kind==='sea'?30:13}seaBed.visible=water?.kind==='sea';if(seaBed.visible){const cx=Math.round(camera.position.x/40)*40,cz=Math.round(camera.position.z/40)*40,key=cx+','+cz;if(key!==bedCell){bedCell=key;const a=bedGeometry.attributes.position;for(let i=0;i<a.count;i++){const x=cx+(i%51/50-.5)*400,z=cz+(Math.floor(i/51)/50-.5)*400;a.setXYZ(i,x,oceanBed(x,z),z);bedGeometry.attributes.uv.setXY(i,x/2,z/2)}a.needsUpdate=true;bedGeometry.attributes.uv.needsUpdate=true;bedGeometry.computeVertexNormals()}}
  for(const r of rings){r.age+=dt;r.mesh.visible=r.age>=0&&r.age<r.life;if(!r.mesh.visible)continue;const t=r.age/r.life;r.mesh.scale.setScalar(.2+t*r.power*2.2);r.mesh.material.opacity=(1-t)*.40*(.15+.85*(lighting?.day??1))}
  for(let i=particles.length-1;i>=0;i--){const p=particles[i];p.life-=dt;if(p.life<=0){particles.splice(i,1);continue}p.vy-=8*dt;p.x+=p.vx*dt;p.y+=p.vy*dt;p.z+=p.vz*dt;}for(let i=0;i<particles.length;i++)positions.set([particles[i].x,particles[i].y,particles[i].z],i*3);particleGeometry.attributes.position.needsUpdate=true;particleGeometry.setDrawRange(0,particles.length);
 }
 return{at,supported,splash,update,get underwater(){return underwater},get splashEvent(){return lastSplash}};
}
